insert into public.community_scams
  (id,city,location,lat,lng,title,category,description,how_to_avoid,
   typical_loss,severity,service_type,red_flags,tags,source)
values
('gwt_001','guwahati','Lokpriya Gopinath Bordoloi Airport',26.1061,91.5859,'Airport Taxi Tout Overcharge','overcharging','Unlicensed taxi touts intercept arrivals before the prepaid counter and quote ₹800–1,200 for a trip to Paltan Bazaar. The fair rate is ₹300–380.','Walk past all touts to the prepaid taxi counter inside the terminal. Fixed rate to city centre is ~₹350. Ola/Uber also available once outside.','₹400–800 extra','high','taxi','["Approaches you before you reach the exit","Refuses to use meter","Quotes a round number like ₹1,000"]'::jsonb,'["airport","overcharging","tout"]'::jsonb,'seed'),
('gwt_002','guwahati','Kamakhya Temple',26.1664,91.649,'Fake Priest VIP Darshan','scam','Men in saffron robes outside the temple offer ''VIP darshan'' bypassing the queue for ₹2,000–5,000. They pocket the money and either vanish or lead you to an unrelated private house.','VIP darshan tickets are sold only at the official temple trust counter at the gate. No legitimate priest solicits outside.','₹2,000–5,000','high','guide','["Approaches proactively","Promises queue bypass","Asks for cash only"]'::jsonb,'["temple","fake_guide","fraud","kamakhya"]'::jsonb,'seed'),
('gwt_003','guwahati','Paltan Bazaar',26.1824,91.7523,'Auto-Rickshaw Tampered Meter','overcharging','Autos in Paltan Bazaar use meters calibrated to run 1.5–2× faster than the legal rate. Short trips of 2–3 km end up costing ₹150–200 instead of ₹50–80.','Agree on a fixed price before boarding. Standard rate is ₹10–12/km. For trips under 3 km, ₹50–80 is typical.','₹70–120 extra','medium','auto','["Driver insists on meter only","Meter ticks unusually fast","Refuses to quote a fixed price"]'::jsonb,'["auto","meter","overcharging","paltan"]'::jsonb,'seed'),
('gwt_004','guwahati','Guwahati Railway Station',26.1836,91.7457,'Fake Porter Baggage Fee','hidden_charge','Unofficial porters grab luggage without quoting a price, carry it 20 metres to the exit, then demand ₹300–500. Licensed porters charge ₹30–50 per bag and wear a red uniform with an ID badge.','Only engage porters wearing red uniforms with visible Railway badge. Agree on the fee before handing over bags.','₹250–450 extra','medium','guide','["No badge or uniform","Grabs bags without asking","Demands payment before you can leave"]'::jsonb,'["station","porter","hidden_charge"]'::jsonb,'seed'),
('gwt_005','guwahati','Fancy Bazaar',26.1872,91.7432,'Silk & Handicraft Quality Fraud','tourist_trap','Shops targeting tourists sell synthetic fabric labelled as Assam silk (muga/eri) at genuine silk prices of ₹2,000–8,000 per metre. The cloth is indistinguishable to untrained eyes.','Buy silk only from Assam Silk stores with GI-tag certification or the Government Silk Emporium on G.S. Road. Rub the fabric — real silk warms quickly.','₹1,500–6,000 per metre','medium','restaurant','["Price seems low for ''pure muga''","Shop has no GI certification displayed","Pressure to buy immediately"]'::jsonb,'["shopping","silk","tourist_trap","fancy_bazaar"]'::jsonb,'seed'),
('gwt_006','guwahati','Brahmaputra Riverfront',26.1889,91.7362,'Boat Ride Hidden Charges','hidden_charge','Boatmen quote ₹100–150 for a Brahmaputra river crossing or sunset cruise, then add charges mid-trip for ''island entry'', ''life jacket fee'', and ''guide fee'' totalling ₹400–600.','Ask explicitly before boarding: ''Is this the total price, no extra charges?'' Government ASTC ferries have fixed printed fares. Agree on an all-inclusive price.','₹300–450 in hidden fees','medium','taxi','["Adds fees mid-journey","No written price board","Claims entry fees are ''government charges''"]'::jsonb,'["boat","hidden_charge","river"]'::jsonb,'seed'),
('shl_001','shillong','Police Bazaar',25.5788,91.8933,'Tourist Taxi Price Inflation','overcharging','Drivers at Police Bazaar quote out-of-state tourists 50–100% above local rates. Cherrapunji return (which locals pay ₹1,200) is quoted at ₹2,500–3,500.','Fair rate: Cherrapunji return ₹1,200–1,800. Ask your hotel to arrange a car or compare with at least two other drivers. Ola is available in Shillong.','₹800–1,500 extra','medium','taxi','["Quotes significantly higher than hotel estimate","Won''t share cab with other passengers","Insists on ''tourist rate''"]'::jsonb,'["overcharging","tourist_price","police_bazaar"]'::jsonb,'seed'),
('shl_002','shillong','Shillong Airport (Umroi)',25.7036,91.9787,'Airport Cab Monopoly Pricing','overcharging','The 35 km Umroi Airport to Police Bazaar route is quoted at ₹1,500–2,000 by unregulated cabs. The official prepaid rate is ₹700–900.','Use the prepaid taxi counter at the arrivals exit. Confirm the price is ₹800 or less before moving to the vehicle.','₹600–1,100 extra','high','taxi','["No prepaid receipt offered","Driver quotes ''fixed tourist rate''","Starts driving before agreeing on price"]'::jsonb,'["airport","overcharging","umroi"]'::jsonb,'seed'),
('shl_003','shillong','Cherrapunji',25.27,91.732,'Fake Waterfall Entry Tickets','scam','Unofficial ticket sellers near Nohkalikai Falls and Seven Sisters Falls charge ₹150–300 entry. The actual Forest Department rate is ₹20–40 per person.','Only buy tickets from the official forest department kiosk at the main gate. It has a printed rate chart. Never buy from individuals on the road.','₹100–260 per person','medium','guide','["Selling tickets away from the main gate","No official receipt","Says ''government rate increased recently''"]'::jsonb,'["entry_fee","fake_ticket","cherrapunji","waterfall"]'::jsonb,'seed'),
('shl_004','shillong','Mawlynnong Village',25.202,91.902,'Unofficial Village Guide Overcharge','overcharging','Self-appointed guides at the ''Cleanest Village in Asia'' charge ₹500–1,000 for a walk that takes 20 minutes and needs no guide. The village is tiny and well-signed.','Mawlynnong is easy to navigate independently. If you want a guide, the community-run visitor centre charges a fair ₹100–200.','₹300–800','low','guide','["Intercepts you at the entrance","Claims village ''requires'' a guide","No official ID"]'::jsonb,'["guide","mawlynnong","overcharging"]'::jsonb,'seed'),
('shl_005','shillong','Shillong',25.5788,91.8933,'Hotel ''Government Approved'' Scam','tourist_trap','Touts near the bus stand steer tourists to specific hotels claiming they are ''government approved'' or ''tourist department certified'' and earn commission. These hotels are often overpriced or substandard.','Book accommodation in advance through reputable platforms. Ignore unsolicited hotel recommendations from strangers at bus/taxi stands.','₹500–2,000 over fair market rate','medium','guide','["Volunteer helper at bus stand","Claims other hotels are ''full'' or ''closed''","Insists on taking you personally"]'::jsonb,'["hotel","tout","tourist_trap"]'::jsonb,'seed'),
('shl_006','shillong','Laitlum Canyons',25.531,91.985,'Unofficial Parking & Entry Fee','hidden_charge','Locals near Laitlum collect ₹100–200 ''parking fees'' and ₹50 per person ''entry fees'' that have no official basis. The area is a community-managed viewpoint with nominal or no entry charge.','Ask for an official receipt. The legitimate community fee (if any) is ₹20–30 per person. Refuse to pay without a proper receipt.','₹150–350 per vehicle','low','taxi','["No printed receipt","Man-made barrier on road","Demands cash before you''ve parked"]'::jsonb,'["parking","hidden_charge","laitlum"]'::jsonb,'seed'),
('gng_001','gangtok','MG Marg',27.3389,88.6065,'Tsomgo + Nathula Package Inflation','overcharging','Travel agents on MG Marg quote ₹5,000–8,000 per car for Tsomgo Lake + Nathula. The fair rate including permits is ₹2,500–3,500. Agents claim inflated ''processing fees'' for permits that cost nothing extra.','Book permits directly at the Tourism & Civil Aviation Dept office. Compare at least 3 agents. Fair private cab rate is ₹2,800–3,200 for both sites.','₹1,500–4,500','high','taxi','["Permit ''processing fee'' over ₹200","Refuses to itemise costs","Claims it''s the ''last available car''"]'::jsonb,'["tour_package","permit","overcharging","tsomgo","nathula"]'::jsonb,'seed'),
('gng_002','gangtok','Bagdogra Airport',26.6812,88.3286,'Bagdogra to Gangtok Overcharge','overcharging','Touts at Bagdogra quote ₹4,000–5,000 for a private cab to Gangtok. Shared taxis from the official stand cost ₹300–350 per seat; private cab fair rate is ₹2,200–2,800.','Head to the official shared taxi stand outside arrivals. For private cab, use pre-booked services or confirm the rate is under ₹2,800 before departure.','₹1,200–2,200','high','taxi','["Intercepts before you reach the taxi stand","No meter or printed rate","Quotes only per-vehicle, not per-seat"]'::jsonb,'["airport","shared_cab","overcharging","bagdogra"]'::jsonb,'seed'),
('gng_003','gangtok','Rumtek Monastery',27.2918,88.5548,'Fake Monastery Guide','fake_service','Unlicensed guides outside Rumtek and Enchey Monastery offer ''exclusive inner sanctum'' access for ₹800–2,000. No such access exists for tourists; they simply walk you around the public courtyard.','Monastery entry is free or has a small donation box. Government-licensed guides carry a laminated Tourism Dept ID card. Pay no more than ₹400–600 for a half-day guide.','₹400–1,600','medium','guide','["Claims to have ''special permission''","No official ID card","Demands payment upfront before entering"]'::jsonb,'["guide","monastery","fake_service","rumtek"]'::jsonb,'seed'),
('gng_004','gangtok','Gangtok',27.3314,88.6138,'Organic Sikkim Product Mislabelling','tourist_trap','Shops sell generic tea, cardamom, and honey labelled as ''certified organic Sikkim'' at 3–5× the price of identical products from Darjeeling or Nepal. The ''organic'' certification is often a printed sticker with no verification.','Buy certified organic Sikkim products from the Sikkim Organic Mission outlet at MG Marg or the State Government Emporium. Ask for the certification number.','₹300–2,000 per purchase','low','restaurant','["No certification number on label","Price drastically higher than market","Sold only to tourists, not locals"]'::jsonb,'["shopping","organic","tourist_trap","mislabel"]'::jsonb,'seed'),
('gng_005','gangtok','Gangtok',27.3314,88.6138,'Hidden Hotel Tax & Service Charge','hidden_charge','Budget guesthouses add ''tourism cess'', ''room service charge'', and ''heater fee'' to the bill that were not mentioned at check-in, inflating the bill by 20–35%.','Ask at check-in for a full breakdown of all charges. Request a written quote. GST is standard (12–18%) but additional local cess or ''heater fee'' should be negotiated upfront.','₹200–600 per night','medium','restaurant','["Bill significantly higher than quoted price","Vague line items like ''miscellaneous''","Reluctant to give itemised bill"]'::jsonb,'["hotel","hidden_charge","tax","gangtok"]'::jsonb,'seed'),
('gng_006','gangtok','Nathula Pass',27.3872,88.8296,'Nathula Permit Middleman','hidden_charge','Agents near the Tourism Office charge ₹300–600 as ''facilitation fees'' to process Nathula permits. The permit itself is free and can be obtained directly at the SDM office with your documents.','Bring original ID, passport photos, and vehicle registration to the Sub-Divisional Magistrate (SDM) office. Processing is free. Your hotel can guide you.','₹300–600','medium','guide','["Offers to ''fast-track'' your permit","Asks for original documents to keep","Works from an unofficial-looking office near the govt building"]'::jsonb,'["permit","hidden_charge","nathula"]'::jsonb,'seed'),
('taw_001','tawang','Tawang',27.586,91.8594,'Bumla Pass Permit Fraud','scam','Agents near Tawang town collect ₹500–1,000 per person for Bumla Pass permits that are completely free. They claim ''special government processing'' is required.','Bumla permits are obtained free at the DC (Deputy Commissioner) office in Tawang with your ILP and passport. No agent is needed. Your hotel can accompany you.','₹500–1,000 per person','high','guide','["Operates from a roadside desk near the DC office","Claims online process is ''not working''","Asks for original documents"]'::jsonb,'["permit","fraud","bumla","tawang"]'::jsonb,'seed'),
('taw_002','tawang','Sela Pass',27.513,92.072,'Fake Photography Permit','scam','Individuals at Sela Lake and the pass viewpoint demand ₹200–500 for a ''photography permit''. No such permit exists. This is entirely fraudulent.','There is no photography fee at Sela Pass. Refuse politely and walk away. If aggressive, note the person''s description and report to the nearest ITBP post.','₹200–500','medium','guide','["Unofficial-looking laminated card","Demands cash before you take a photo","Amount changes when you question it"]'::jsonb,'["fake_fee","photography","sela"]'::jsonb,'seed'),
('taw_003','tawang','Tezpur–Tawang Highway',27.1,92.1,'Mid-Route Fare Revision','overcharging','Hired drivers on the Tezpur–Tawang route claim road closures, military checkpoints, or ''extra fuel costs'' mid-journey to demand ₹500–1,500 above the agreed fare.','Fix the fare in writing on a signed paper before departure. Clarify: ''This price is final regardless of road conditions.'' Use hotel-recommended drivers only.','₹500–1,500','high','taxi','["Mentions road problems shortly after departure","Stops at a dhaba and ''discusses'' costs","Says he needs extra for ''toll'' on a free road"]'::jsonb,'["driver","overcharging","route_change","tezpur_tawang"]'::jsonb,'seed'),
('taw_004','tawang','Tawang Monastery',27.5873,91.8617,'Monastery Souvenir Price Gouging','tourist_trap','Souvenir stalls inside and around Tawang Monastery sell thangka paintings, prayer flags, and singing bowls at 3–10× their actual value, targeting foreign and domestic tourists equally.','Compare prices at the local market in Tawang town (10 min walk). Singing bowls: ₹300–500 fair; prayer flags: ₹30–80 per string. Bargain confidently.','₹500–3,000 per item','low','restaurant','["Price drops dramatically when you hesitate","Claims items are ''monastery-blessed'' and unique","No price tags displayed"]'::jsonb,'["souvenir","tourist_trap","monastery","tawang"]'::jsonb,'seed'),
('taw_005','tawang','Tawang',27.586,91.8594,'ILP Facilitation Fee Scam','scam','Agents near transport hubs charge ₹300–800 to ''arrange'' Inner Line Permits for Arunachal Pradesh. ILPs are free and can be obtained online at the Arunachal online portal or at any DC/SDM office.','Apply online at arunachalipr.gov.in (free) or at the DC/SDM office in person. No agent needed. Carry printout of your ILP at all times.','₹300–800','high','guide','["Claims online portal ''is down''","Asks for money before showing you the process","Works outside the government office building"]'::jsonb,'["ILP","permit","fraud","arunachal"]'::jsonb,'seed'),
('kaz_001','kaziranga','Kaziranga National Park (Kohora Gate)',26.5759,93.1574,'Unofficial Jeep Safari Tickets','scam','Touts sell jeep safari tickets outside the gate for ₹2,000–3,000 per person. Official Forest Dept jeep safari is ₹700–900 per seat including park entry.','Book only at official counters inside the gate (Kohora, Bagori, Agaratoli ranges). Carry original ID. Online booking available at kaziranga.nic.in.','₹1,100–2,100 per person','high','guide','["Ticket has no Forest Dept stamp","Sold outside the park compound","Price includes no itemisation"]'::jsonb,'["safari","fake_ticket","overcharging","kaziranga"]'::jsonb,'seed'),
('kaz_002','kaziranga','Kohora',26.5759,93.1574,'Resort Taxi Overcharge','overcharging','Resort-arranged taxis to Jorhat or Furkating charge ₹1,500–2,000 for routes that cost locals ₹700–900. Resorts add an undisclosed commission.','Ask the resort to call a local taxi directly, not through their ''partner''. Fair rate: Jorhat ₹800–1,000, Furkating ₹500–600, Guwahati shared cab ₹300/seat.','₹600–1,100','medium','taxi','["Resort insists on ''their driver only''","Driver is unfamiliar with local fares","No receipt provided"]'::jsonb,'["hotel","overcharging","resort","kaziranga"]'::jsonb,'seed'),
('kaz_003','kaziranga','Kaziranga',26.582,93.168,'Fake Wildlife Guide Certification','fake_service','Guides without Assam Forest Department certification pose as licensed wildlife naturalists, charging ₹1,500–2,500/day for a service a certified guide provides for ₹600–800.','Ask to see the green Assam Forest Department guide badge with photo ID. Book through the official guide counter at the park gate. Certified guides also know animal locations better.','₹700–1,700','medium','guide','["No green Forest Dept badge","Approaches you outside the park","Offers a ''package'' combining guide + jeep"]'::jsonb,'["guide","fake_certification","kaziranga"]'::jsonb,'seed'),
('kaz_004','kaziranga','Kaziranga National Park',26.5775,93.1711,'Elephant Safari Hidden Charges','hidden_charge','Touts for elephant safaris quote ₹400–500 per person then add ''mahout tip'', ''camera fee'', ''insurance'', and ''park contribution'' to charge ₹900–1,200 total.','Elephant safaris are ₹900–1,200 all-inclusive when booked at the official Forest Dept counter. All charges should be on the receipt. Tip the mahout separately at your discretion (₹50–100).','₹400–700 in hidden fees','medium','guide','["Initial price seems unusually low","Fees added after you''ve mounted the elephant","No printed receipt for each charge"]'::jsonb,'["elephant","safari","hidden_charge","kaziranga"]'::jsonb,'seed'),
('kaz_005','kaziranga','Kaziranga',26.5775,93.1711,'Roadside Restaurant Tourist Menu','tourist_trap','Roadside dhabas near the park hand tourists a separate ''tourist menu'' with prices 2–3× the regular menu. A thali that costs locals ₹80–100 is charged at ₹200–300.','Ask to see the regular menu or ask other diners what they paid. A full Assamese thali should cost ₹80–150 anywhere along NH-37.','₹100–200 per meal','low','restaurant','["Menu brought out only after seeing you''re a tourist","No prices on the board outside","Staff hesitant to quote price before ordering"]'::jsonb,'["restaurant","tourist_menu","hidden_charge","kaziranga"]'::jsonb,'seed')
on conflict (id) do nothing;